package com.kirjasto.kirjastobotti

/** Provider-neutral, touch-first catalogue UI displayed locally on Temi. */
object TemiCatalogueUi {
    fun html(libraryName: String, officialCatalogueUrl: String): String = """
        <!doctype html><html lang="fi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
        <style>
        :root{--s:#101820;--r:#26343D;--t:#F7F9FB;--m:#B8C4CC;--a:#1976A8;--l:#8DD8FF}*{box-sizing:border-box}body{margin:0;background:var(--s);color:var(--t);font:28px/1.3 Roboto,Arial,sans-serif}button,input{font:inherit}button{min-height:88px;border:0;border-radius:24px;padding:12px 28px;color:var(--t);font-weight:700}button:focus,input:focus{outline:4px solid var(--l);outline-offset:4px}.primary{background:var(--a)}.secondary{background:var(--r)}.link{min-height:68px;background:none;color:var(--l);padding:6px 12px}.frame{height:100vh;min-height:720px;display:grid;grid-template-rows:120px 1fr 112px}.header,.footer{display:flex;align-items:center;gap:28px;padding:0 64px;background:#0c1319}.header{border-bottom:1px solid #40515c}.footer{justify-content:space-between;border-top:1px solid #40515c;font-size:24px}.footer button{min-height:72px}.brand{font-size:34px;font-weight:700}.brand b,.shelf,.tabs{color:var(--l)}.library{margin-left:auto;color:var(--m);font-size:26px}.locale{min-height:72px;padding:8px 20px}.content{padding:48px 64px;overflow:auto}.screen{max-width:1600px;margin:auto}.welcome{text-align:center;max-width:1320px;margin:80px auto}.welcome h1,.detail h1,.confirm h1{font-size:48px;margin:0 0 8px}.subtitle,.meta,.hint,.guidance{color:var(--m)}.subtitle{margin:0 0 44px}.searchrow,.head{display:flex;gap:20px;align-items:center}.search{height:96px;flex:1;border-radius:24px;border:3px solid #50616d;background:#fff;color:#14212a;padding:0 28px;font-size:28px}.choices{display:flex;justify-content:center;gap:24px;margin:28px 0}.count{color:var(--m);margin:20px 0}.card{display:grid;grid-template-columns:190px 1fr auto;gap:28px;align-items:center;background:var(--r);padding:24px;border-radius:24px;margin:16px 0;min-height:190px}.cover{height:142px;border-radius:16px;background:#3b5968;display:flex;align-items:center;justify-content:center;color:var(--l);font-size:56px}.title{font-size:34px;font-weight:700}.status{margin-top:12px;font-weight:700}.good{color:#6ee1a4}.warn{color:#ffd075}.actions{display:flex;gap:14px;flex-wrap:wrap;justify-content:flex-end}.actions button{min-height:72px;padding:10px 22px}.availability{background:var(--r);padding:32px;border-radius:24px;display:flex;gap:28px;align-items:center;margin:34px auto;max-width:1280px}.availabilitymain{flex:1}.tabs{text-align:center;margin:34px}.confirm{text-align:center;max-width:900px;margin:90px auto}.confirm button{display:block;width:100%;margin:16px 0}.notice{background:#1b2a33;padding:24px;border-radius:20px;color:var(--m);margin:24px 0}.languages{position:absolute;right:64px;top:105px;background:var(--r);padding:12px;border-radius:20px;z-index:2}.languages button{display:block;width:100%;min-height:64px;text-align:left}.hidden{display:none!important}@media(max-width:1000px){.content{padding:32px 48px}.card{grid-template-columns:150px 1fr}.actions{grid-column:1/-1;justify-content:start}.availability{display:block}.header,.footer{padding:0 48px}.library{display:none}}
        </style></head><body><div class="frame"><header class="header"><div class="brand">◉ <b>Kirjastobotti</b></div><div class="library">%%LIBRARY%%</div><button class="secondary locale" onclick="languages()" aria-label="Vaihda kieli">FI</button><button class="secondary locale" onclick="help()" aria-label="Ohje">?</button><div id="langs" class="languages hidden"><button class="link" onclick="language('FI')">Suomi</button><button class="link" onclick="language('EN')">English</button><button class="link" onclick="language('SV')">Svenska</button></div></header><main id="app" class="content" aria-live="polite"></main><footer class="footer"><button class="secondary" onclick="home()">⌂ Home</button><div id="guide" class="guidance">Etsi kirja tai aihe</div><button class="secondary" onclick="back()">← Back</button></footer></div><script>
        var page='home',query='',selected=null,official='%%URL%%';var books=[{id:'m1',title:'Muumipappa ja meri',author:'Tove Jansson',format:'Kirja',language:'suomi',status:'Saatavilla täällä',shelf:'84.2 JAN',available:true},{id:'m2',title:'Muumilaakson marraskuu',author:'Tove Jansson',format:'Kirja',language:'suomi',status:'Lainassa',shelf:'',available:false},{id:'m3',title:'The Summer Book',author:'Tove Jansson',format:'Book',language:'English',status:'Tarkista henkilökunnalta',shelf:'',available:false}];
        function esc(v){return String(v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')}function card(b){var s=b.available?'good':'warn',i=b.available?'✓':'!',x=b.shelf?'<button class="primary" onclick="event.stopPropagation();pick(\''+b.id+'\');confirm()">Take me</button>':'<button class="secondary" onclick="event.stopPropagation();details(\''+b.id+'\')">View availability</button>';return '<article class="card" tabindex="0" onclick="details(\''+b.id+'\')"><div class="cover" aria-hidden="true">▣</div><div><div class="title">'+esc(b.title)+'</div><div class="meta">'+esc(b.author)+' · '+esc(b.format)+' · '+esc(b.language)+'</div><div class="status '+s+'">'+i+' '+esc(b.status)+(b.shelf?' · Shelf '+esc(b.shelf):'')+'</div></div><div class="actions"><button class="secondary" onclick="event.stopPropagation();details(\''+b.id+'\')">View book</button>'+x+'</div></article>'}
        function render(){var a=document.getElementById('app'),g=document.getElementById('guide');g.textContent=page==='guide'?'Ohjaus käynnissä':page==='details'?'Katso saatavuus ja hylly':'Etsi kirja tai aihe';if(page==='home')a.innerHTML='<section class="screen welcome"><h1>Find a book</h1><p class="subtitle">Search this library\'s collection</p><div class="searchrow"><input id="q" class="search" aria-label="Hae kirjaa" placeholder="🔎 Title, author, subject, or ISBN" value="'+esc(query)+'" onkeydown="if(event.key===\'Enter\')search()"><button class="secondary" onclick="listen(this)">Speak</button></div><div class="choices"><button class="secondary" onclick="topic()">Browse popular topics</button><button class="secondary" onclick="scan()">Scan a book ISBN</button></div><p class="hint">You can ask me to take you to a shelf after you find a book.</p></section>';else if(page==='results'){var m=books.filter(function(b){return !query||(b.title+b.author).toLowerCase().indexOf(query.toLowerCase())>=0});a.innerHTML='<section class="screen"><div class="head"><label>Search:</label><input id="q" class="search" value="'+esc(query)+'" aria-label="Hakusana" onkeydown="if(event.key===\'Enter\')search()"><button class="primary" onclick="search()">Search</button></div><div class="count">'+m.length+' results &nbsp;&nbsp; Sort: Best match</div>'+(m.length?m.map(card).join(''):'<div class="notice">No results found. Try a title, an author, or a topic such as history.<br><button class="link" onclick="openOfficial()">Search official catalogue</button></div>')+'</section>'}else if(page==='details'){var b=selected,button=b.shelf?'<button class="primary" onclick="confirm()">Take me to this shelf</button>':'<button class="secondary" onclick="openOfficial()">View availability</button>';a.innerHTML='<section class="screen detail"><div style="text-align:center"><h1>'+esc(b.title)+'</h1><p class="subtitle">'+esc(b.author)+' · '+esc(b.format)+' · '+esc(b.language)+'</p></div><div class="availability"><div class="availabilitymain"><strong>Availability at %%LIBRARY%%</strong><div class="status '+(b.available?'good':'warn')+'">'+(b.available?'✓':'!')+' '+esc(b.status)+'</div>'+(b.shelf?'<div class="shelf">Shelf: '+esc(b.shelf)+'</div>':'<div class="meta">A staff member can help locate this item.</div>')+'</div>'+button+'</div><div class="tabs">About this book &nbsp; • &nbsp; Other editions &nbsp; • &nbsp; More availability</div></section>'}else if(page==='confirm')a.innerHTML='<section class="confirm"><h1>Ready to guide you</h1><p class="subtitle">'+esc(selected.title)+'</p><div class="shelf">Shelf '+esc(selected.shelf)+'</div><button class="primary" onclick="start()">Start guidance</button><button class="secondary" onclick="details(selected.id)">Not now</button></section>';else if(page==='guide')a.innerHTML='<section class="confirm"><div class="cover" style="height:220px">→</div><h1>Guiding you to</h1><p class="subtitle">'+esc(selected.title)+'</p><div class="shelf">Shelf '+esc(selected.shelf)+'</div><p class="notice">Please stay near me. I will announce when we arrive.</p><button class="secondary" onclick="stop()">Stop guidance</button></section>';else a.innerHTML='<section class="confirm"><h1>How to search</h1><p class="subtitle">Type a title, author, topic, or ISBN. Select a book to see if it is available here.</p><p class="notice">Ask staff for help if you need help finding an item or using the library.</p><button class="primary" onclick="home()">Return home</button></section>'}
        function pick(id){selected=books.find(function(x){return x.id===id})}function search(){query=document.getElementById('q').value.trim();page='results';render()}function details(id){pick(id);page='details';render()}function confirm(){page='confirm';render()}function start(){page='guide';render();Android.requestShelf(selected.shelf)}function stop(){try{Android.stopGuidance()}catch(e){}home()}function home(){page='home';query='';selected=null;render()}function back(){if(page==='home')return;if(page==='results')home();else if(page==='details')page='results';else if(page==='confirm')page='details';else home();render()}window.kirjastobottiBack=back;function help(){page='help';render()}function languages(){document.getElementById('langs').classList.toggle('hidden')}function language(l){document.querySelector('.locale').textContent=l;languages()}function listen(b){document.getElementById('guide').textContent='Listening… Tap Stop listening when you are done.';b.textContent='Stop listening';b.onclick=function(){b.textContent='Speak';b.onclick=function(){listen(b)}}}function topic(){query='history';page='results';render()}function scan(){document.getElementById('guide').textContent='ISBN scanning is ready when a camera is available.'}function openOfficial(){window.location.href=official}render();
        </script></body></html>
    """.trimIndent().replace("%%LIBRARY%%", libraryName.html()).replace("%%URL%%", officialCatalogueUrl.html())
    private fun String.html() = replace("&", "&amp;").replace("'", "&#39;").replace("\"", "&quot;").replace("<", "&lt;").replace(">", "&gt;")
}
